class HRManagementSystem:
    VALID_EMPLOYEE_KEYS = {'name', 'position', 'department', 'salary'}

    def __init__(self):
        self.__employees = {}

    def add_employee(self, employee_id, name, position, department, salary):
        self.update_employee(employee_id, {
            'name': name,
            'position': position,
            'department': department,
            'salary': salary
        }, is_new=True)
        return employee_id in self.__employees

    def remove_employee(self, employee_id):
        if employee_id not in self.__employees:
            return False
        del self.__employees[employee_id]
        return True

    def update_employee(self, employee_id: int, employee_info: dict, is_new: bool = False):
        if not is_new and employee_id not in self.__employees:
            return False

        if employee_id in self.__employees:
            self.__validate_employee_data(employee_info)
            self.__employees[employee_id].update(employee_info)
        else:
            self.__employees[employee_id] = employee_info

        return True

    def get_employee(self, employee_id):
        return self.__employees.get(employee_id)

    def list_employees(self):
        return {eid: dict(info) for eid, info in self.__employees.items()}

    def __validate_employee_data(self, employee_info):
        if not isinstance(employee_info, dict):
            raise ValueError("Employee info must be a dictionary")

        invalid_keys = set(employee_info.keys()).difference(self.VALID_EMPLOYEE_KEYS)
        if invalid_keys:
             return False

        return True
